UPDATE sch04_list
   SET sch04_person_id   = #{personId}
     , sch04_manage_date = #{manageDate}
     , sch04_status_cd   = #{statusCode}
 WHERE sch04_list_id    = #{listId}
   AND sch04_company_id = #{companyId}

UPDATE sch04_list
   SET sch04_note = #{note}
 WHERE sch04_list_id    = #{listId}
   AND sch04_company_id = #{companyId}

UPDATE sch04_list
   SET sch04_confirm_yn   = #{confirmYn}
     , sch04_confirm_date = #{confirmDate}
     , sch04_confirmer_id = #{confirmerId}
 WHERE sch04_list_id    = #{listId}
   AND sch04_company_id = #{companyId}
